function onboardingPanel(){
 const steps=[
  {label:"Create your first creative brief",detail:"Define the audience, promise and visual direction.",tab:"director",done:state.projects.length>0},
  {label:"Build a series or episode plan",detail:"Turn an idea into episodes, scenes and shot-ready direction.",tab:"series",done:state.seriesPlans.length>0},
  {label:"Bring in source media",detail:"Add reference images, audio or video before editing.",tab:"library",done:state.assets.length>0}
 ];
 const completed=steps.filter(item=>item.done).length;
 if(completed===steps.length)return "";
 return '<section class="onboarding-panel" aria-labelledby="onboarding-title"><div class="onboarding-heading"><div><div class="eyebrow">YOUR FIRST PRODUCTION · GETTING STARTED</div><h2 id="onboarding-title">Build your first project</h2><p>Three practical steps take you from an idea to an editable production workspace. Complete them in any order.</p></div><div class="onboarding-progress" role="progressbar" aria-label="Getting started progress" aria-valuemin="0" aria-valuemax="'+steps.length+'" aria-valuenow="'+completed+'"><b>'+completed+'/'+steps.length+'</b><small>complete</small></div></div><div class="onboarding-meter"><i style="width:'+(completed/steps.length*100)+'%"></i></div><div class="onboarding-steps">'+steps.map((item,index)=>'<article class="onboarding-step '+(item.done?'is-complete':'')+'"><span class="onboarding-step-number">'+(item.done?'✓':String(index+1).padStart(2,"0"))+'</span><div><b>'+item.label+'</b><p>'+item.detail+'</p></div><button class="'+(item.done?'quiet':'secondary')+'" data-tab="'+item.tab+'" '+(item.done?'disabled aria-label="Completed"':'')+'>'+(item.done?'Completed':'Start step →')+'</button></article>').join("")+'</div></section>';
}
function continuePanel(){
 const briefs=state.projects.slice().sort((a,b)=>b.created.localeCompare(a.created)).slice(0,3);
 const seriesItems=state.seriesPlans.slice(0,3);
 const briefCards=briefs.map(project=>'<article class="continue-card"><div><small>'+esc(project.style)+' · '+(project.creativeDNA?.completenessScore??"—")+'% brief coverage</small><b>'+esc(project.name)+'</b><p>'+esc(project.brief.slice(0,150))+(project.brief.length>150?"…":"")+'</p><span>'+esc(project.audience||"Audience not specified")+'</span></div><button class="secondary" data-resume-project="'+esc(project.id)+'">Continue brief →</button></article>').join("");
 const seriesCards=seriesItems.map(item=>'<article class="continue-card"><div><small>'+esc(item.format)+' · '+item.seasons.reduce((n,season)=>n+season.episodes.length,0)+' episodes</small><b>'+esc(item.title)+'</b><p>'+esc(item.premise.slice(0,150))+(item.premise.length>150?"…":"")+'</p><span>'+item.seasons.length+' season(s) · '+item.defaults.episodeRuntimeSeconds+'s target runtime</span></div><button class="secondary" data-resume-series="'+esc(item.id)+'">Continue series →</button></article>').join("");
 if(!briefCards&&!seriesCards)return "";
 return '<section class="continue-panel"><div class="section-title"><div><div class="eyebrow">YOUR RECENT WORK · BROWSER PLANNING DRAFTS</div><h2>Continue where you left off</h2></div><span class="muted">Local planning workspace</span></div><div class="continue-grid">'+(briefCards||'<div class="empty">No creative briefs yet.</div>')+(seriesCards||'<div class="empty">No series plans yet.</div>')+'</div></section>';
}
function home(){return header("EXECUTIVE VISUALS · CREATIVE PRODUCTION","A clearer path from brief to finished work.","Plan a production, develop its visual direction, create and edit media, then prepare deliverables for review.",'<button class="primary" data-tab="director">＋ New production brief</button>')+onboardingPanel()+
'<div class="hero"><div><span class="eyebrow">YOUR PRODUCTION WORKSPACE</span><h2>Make the work.<br><em>Keep every step connected.</em></h2><p>Bring the brief, scenes, source media, edits and final exports together. Start with a project and move through each stage with a clear record of what is ready and what still needs an engine.</p><button class="light" data-tab="cloud">View projects →</button></div><div class="hero-art"><div class="orbit-card"><small>EXECUTIVE VISUALS</small><b>Production, in one place</b><i>PLAN · CREATE · EDIT · DELIVER</i></div></div></div>'+
renderRuntimeOverview()+continuePanel()+
'<div class="section-title"><div class="eyebrow">PRODUCTION TOOLS</div><h2>Workspaces</h2></div><div class="module-grid">'+tabs.filter(t=>!["home","settings"].includes(t.id)).map(t=>'<button class="module" data-tab="'+t.id+'"><i>'+t.icon+'</i><b>'+t.label+'</b><small>'+moduleDesc(t.id)+'</small><span>Open workspace ↗</span></button>').join("")+'</div><div class="section-title"><div class="eyebrow">RECENT ACTIVITY</div><h2>Production tasks</h2></div>'+list(state.tasks.slice(0,5));}
function series(){
 const active=state.seriesPlans.find(item=>item.id===state.activeSeriesId);
 const cards=state.seriesPlans.map(item=>'<article class="project"><small>'+esc(item.format.toUpperCase())+' · '+item.seasons.length+' SEASON(S)</small><b>'+esc(item.title)+'</b><p>'+esc(item.premise)+'</p><span>'+item.seasons.reduce((n,s)=>n+s.episodes.length,0)+' episodes · '+item.defaults.episodeRuntimeSeconds+'s each</span><button class="secondary" data-series-open="'+esc(item.id)+'">Open production</button></article>').join("");
 return header("EPISODIC PRODUCTION SYSTEM","Series producer","Organise projects into series, seasons, episodes, scenes and shot-ready clips. Finished episodes are capped at five minutes; each shot remains within the selected clip duration.",'<button class="secondary" data-action="export">Export production data</button>')+
 '<div class="two-col"><section class="panel"><div class="eyebrow">01 · SERIES BIBLE</div><h2>Create a series</h2><form id="series-create"><label>Series title</label><input name="title" maxlength="120" required placeholder="Future Makers"><label>Series premise</label><textarea name="premise" rows="3" maxlength="3000" required placeholder="What is this series about, who is it for, and why should viewers return?"></textarea><div class="form-grid"><div><label>Format</label><select name="format"><option value="documentary">Documentary</option><option value="docuseries">Docuseries</option><option value="education">Educational series</option><option value="fiction">Fiction / drama</option><option value="interview">Interview / talk show</option><option value="brand">Brand / campaign series</option><option value="children">Family / children</option><option value="shorts">Short-form episodic</option></select></div><div><label>Genre / subject</label><input name="genre" placeholder="Science, culture, business…"></div></div><div class="form-grid"><div><label>Seasons</label><select name="seasonCount"><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select></div><div><label>Episodes per season</label><select name="episodesPerSeason"><option>3</option><option>4</option><option selected>6</option><option>8</option><option>10</option><option>12</option></select></div></div><div class="form-grid"><div><label>Episode runtime</label><select name="episodeRuntimeSeconds"><option value="30">30 seconds</option><option value="60">1 minute</option><option value="90">1.5 minutes</option><option value="120">2 minutes</option><option value="180" selected>3 minutes</option><option value="240">4 minutes</option><option value="300">5 minutes</option><option value="600">10 minutes</option><option value="900">15 minutes</option><option value="1200">20 minutes</option><option value="1800">30 minutes · maximum</option></select></div><div><label>Shot / clip target</label><select name="shotLengthSeconds"><option>4</option><option>6</option><option selected>8</option><option>10</option><option>15</option><option>20</option><option>30</option></select></div></div><div class="form-grid"><div><label>Aspect ratio</label><select name="aspectRatio"><option>16:9</option><option>9:16</option><option>1:1</option><option>4:3</option><option>21:9</option></select></div><div><label>Frame rate</label><select name="frameRate"><option value="24">24 fps · cinematic</option><option value="25">25 fps · broadcast</option><option value="30" selected>30 fps · digital</option><option value="50">50 fps</option><option value="60">60 fps</option></select></div></div><div class="form-grid"><div><label>Master resolution</label><select name="resolution"><option>1080p</option><option selected>1440p</option><option>2160p · 4K</option></select></div><div><label>Visual direction</label><select name="visualStyle"><option>Cinematic realism</option><option>Documentary naturalism</option><option>Premium commercial</option><option>Stylised animation</option><option>Editorial / photoreal</option><option>Mixed-media</option></select></div></div><div class="form-grid"><div><label>Language</label><input name="language" value="English" maxlength="40"></div><div><label>Voice approach</label><select name="voiceMode"><option>Natural narration</option><option>Character dialogue</option><option>Presenter-led</option><option>Interview-led</option><option>No voice · visual storytelling</option></select></div></div><div class="form-grid"><div><label>Camera language</label><select name="cameraLanguage"><option>Mixed cinematic coverage</option><option>Locked-off / tripod</option><option>Handheld documentary</option><option>Gimbal / steadicam</option><option>Drone / aerial</option><option>Macro / detail</option><option>Dynamic motion</option></select></div><div><label>Shot composition</label><select name="shotComposition"><option>Mixed shot scale</option><option>Wide establishing</option><option>Medium coverage</option><option>Close-up / emotional</option><option>Vertical mobile-first</option><option>Symmetrical / graphic</option></select></div></div><div class="form-grid"><div><label>Story pacing</label><select name="pacing"><option>Cinematic dramatic</option><option>Measured documentary</option><option>Fast social-first</option><option>Conversational</option><option>High-energy montage</option></select></div><div><label>Color grade</label><select name="colorGrade"><option>Natural / true-to-life</option><option>Warm filmic</option><option>Cool / scientific</option><option>High contrast</option><option>Soft pastel</option><option>Neutral broadcast</option></select></div></div><div class="form-grid"><div><label>Captions</label><select name="captions"><option>Burned-in captions</option><option>Separate subtitle track</option><option>Both</option><option>None</option></select></div><div><label>Music direction</label><select name="music"><option>Adaptive cinematic score</option><option>Documentary atmospheric</option><option>Minimal / restrained</option><option>Energetic / upbeat</option><option>No music</option></select></div></div><label>Continuity / production notes</label><textarea name="continuity" rows="2" maxlength="2000" placeholder="Recurring presenter, wardrobe rules, locations, brand rules, tone…"></textarea><button class="primary wide">＋ Build series, seasons and episode plans</button></form></section><section class="panel"><div class="eyebrow">02 · SERIES LIBRARY</div><h2>Your productions</h2>'+(cards||'<div class="empty">No series yet. Create a series bible to organise your first season.</div>')+'</section></div>'+
 (active?'<section class="panel"><div class="eyebrow">ACTIVE PRODUCTION · '+esc(active.format.toUpperCase())+'</div><h2>'+esc(active.title)+'</h2><p>'+esc(active.premise)+'</p><p>'+active.defaults.episodeRuntimeSeconds+'s per episode · '+esc(active.defaults.aspectRatio)+' · '+active.defaults.frameRate+' fps · '+esc(active.defaults.resolution)+' · '+esc(active.defaults.visualStyle)+' · '+esc(active.defaults.cameraLanguage)+' · '+esc(active.defaults.pacing)+' · '+esc(active.defaults.colorGrade)+'</p><b>Continuity bible</b><p>'+esc(active.continuityNotes||"Add recurring character, wardrobe, location and visual rules before generation.")+'</p><div class="section-title"><div class="eyebrow">STORY-WORLD REGISTRY</div><h3>Characters, places, props and rules</h3></div><form id="series-bible-entry" class="form-grid"><select name="kind"><option value="character">Character / presenter</option><option value="location">Location</option><option value="prop">Prop</option><option value="wardrobe">Wardrobe</option><option value="voice">Voice identity</option><option value="brand-rule">Brand rule</option></select><input name="name" required maxlength="120" placeholder="Record name"><textarea name="description" required maxlength="2000" placeholder="Identity, role, appearance or purpose"></textarea><textarea name="visualRules" maxlength="2000" placeholder="Continuity rules: appearance, behaviour, camera or lighting constraints"></textarea><input name="tags" placeholder="Tags, separated by commas"><input name="referenceAssetIds" placeholder="Optional reference asset IDs, comma separated"><button class="secondary">＋ Add to story bible</button></form><div class="project-grid">'+(active.storyBible?.entries||[]).map(entry=>'<article class="project"><small>'+esc(entry.kind.toUpperCase())+' · '+entry.referenceAssetIds.length+' REFERENCE(S)</small><b>'+esc(entry.name)+'</b><p>'+esc(entry.description)+'</p><span>'+esc(entry.visualRules||entry.tags.join(" · ")) +'</span></article>').join("")+'</div>'+active.seasons.map(season=>'<div class="section-title"><div class="eyebrow">SEASON '+season.number+'</div><h2>'+esc(season.title)+'</h2></div><div class="project-grid">'+season.episodes.map(ep=>'<article class="project"><small>EPISODE '+String(ep.number).padStart(2,"0")+' · '+ep.runtimeSeconds+' SEC · '+ep.scenes.length+' SCENES</small><b>'+esc(ep.title)+'</b><p>'+ep.scenes.map(scene=>'<div class="scene-binding"><span>'+esc(scene.title)+' ('+scene.durationSeconds+'s)</span><form class="form-grid" data-series-scene-bible="'+esc(ep.id)+'" data-scene-id="'+esc(scene.id)+'"><label>Continuity records for this scene<select name="entryIds" multiple size="3">'+(active.storyBible?.entries||[]).map(entry=>'<option value="'+esc(entry.id)+'" '+((scene.storyBibleEntryIds||[]).includes(entry.id)?'selected':'')+'>'+esc(entry.kind.toUpperCase()+' · '+entry.name)+'</option>').join('')+'</select></label><button class="secondary">Save scene references</button></form>'+'<details class="episode-shot-details"><summary>'+scene.shots.length+' shot direction & continuity controls</summary>'+scene.shots.map((shot,index)=>'<form class="form-grid shot-direction" data-series-shot-direction="'+esc(ep.id)+'" data-scene-id="'+esc(scene.id)+'" data-shot-id="'+esc(shot.id)+'"><small>SHOT DIRECTION · '+String(index+1).padStart(2,"0")+'</small><label>Action / prompt<textarea name="prompt" maxlength="2000" rows="2">'+esc(shot.prompt)+'</textarea></label><div class="form-grid"><label>Camera<input name="camera" maxlength="240" value="'+esc(shot.camera||"")+'" placeholder="e.g. slow dolly-in"></label><label>Framing<input name="framing" maxlength="160" value="'+esc(shot.framing||"")+'" placeholder="e.g. medium close-up"></label><label>Movement<input name="movement" maxlength="240" value="'+esc(shot.movement||"")+'" placeholder="e.g. subject crosses frame left to right"></label><label>Lens<input name="lens" maxlength="120" value="'+esc(shot.lens||"")+'" placeholder="e.g. 50mm natural perspective"></label></div><label>Negative prompt<textarea name="negativePrompt" maxlength="1200" rows="2">'+esc(shot.negativePrompt||"")+'</textarea></label><button class="secondary">Save shot direction</button></form><form class="form-grid shot-binding" data-series-shot-bible="'+esc(ep.id)+'" data-scene-id="'+esc(scene.id)+'" data-shot-id="'+esc(shot.id)+'"><small>SHOT '+String(index+1).padStart(2,"0")+' · '+shot.durationSeconds+' SEC</small><label>'+esc(shot.prompt)+'<select name="entryIds" multiple size="2">'+(active.storyBible?.entries||[]).map(entry=>'<option value="'+esc(entry.id)+'" '+((shot.storyBibleEntryIds||[]).includes(entry.id)?'selected':'')+'>'+esc(entry.kind.toUpperCase()+' · '+entry.name)+'</option>').join('')+'</select></label><button class="secondary">Save shot references</button></form>').join('')+'</details></div>').join('')+'</p><span>'+ep.scenes.reduce((n,scene)=>n+scene.shots.length,0)+' planned clips · '+ep.status+'</span><form class="form-grid" data-episode-overrides="'+esc(ep.id)+'"><label>Runtime<select name="episodeRuntimeSeconds"><option value="">Series default</option><option value="30">30 sec</option><option value="60">1 min</option><option value="90">1.5 min</option><option value="120">2 min</option><option value="180">3 min</option><option value="240">4 min</option><option value="300">5 min</option><option value="600">10 min</option><option value="900">15 min</option><option value="1200">20 min</option><option value="1800">30 min</option></select></label><label>Aspect ratio<select name="aspectRatio"><option value="">Series default</option><option>16:9</option><option>9:16</option><option>1:1</option><option>4:3</option><option>3:4</option><option>21:9</option></select></label><label>Visual style<input name="visualStyle" maxlength="80" placeholder="Inherit series visual style"></label><label>Camera language<input name="cameraLanguage" maxlength="100" placeholder="Inherit series camera language"></label><button class="secondary">Save episode overrides</button><button type="button" class="secondary" data-series-reset-overrides="' + esc(ep.id) + '">Reset to series defaults</button></form><button class="secondary" data-series-shot-package="'+esc(ep.id)+'">Download shot package ↓</button><button class="secondary" data-series-timeline="'+esc(ep.id)+'">Create editing timeline ↗</button></article>').join("")+'</div>').join("")+'<p class="muted">These are editable planning scaffolds, not generated scripts or rendered media. Generation requires a compatible engine and approval.</p><button class="primary" data-action="publish-series-cloud">Save series to cloud project ↗</button></section>':'');
}

function modelCreativeDirectionPanel(){
 const project=state.projects.find(item=>item.id===state.activeProject),direction=project?.modelCreativeDirection;
 const section=(label:string,items:string[])=>items.length?'<div class="section-title"><div class="eyebrow">'+esc(label)+'</div></div><ul>'+items.map(item=>'<li>'+esc(item)+'</li>').join('')+'</ul>':'';
 const routes=direction?.creativeRoutes.map(route=>'<article class="project"><small>'+esc(route.name)+'</small><b>'+esc(route.angle)+'</b><p>'+esc(route.tradeoff)+'</p></article>').join('')||'';
 const body=(state.directorAiBusy?'<p class="muted">The configured text model is analysing the brief. No image or video provider is being called.</p>':'')+(state.directorAiMessage?'<p class="notice">'+esc(state.directorAiMessage)+'</p>':'')+(direction?'<div class="creative-plan-meta"><span class="status">Model-backed proposal</span><span>'+esc(direction.generatedAt)+'</span><span>Input fingerprint '+esc(direction.inputHash.slice(0,12))+'…</span></div><h3>'+esc(direction.creativePromise)+'</h3><p>'+esc(direction.strategicThesis)+'</p><p class="muted">'+esc(direction.audienceContract)+'</p><div class="project-grid">'+routes+'</div>'+section("EMOTIONAL JOURNEY",direction.emotionalJourney)+section("HOOK OPTIONS",direction.hookAngles)+section("STORY BEATS",direction.storyBeats)+section("VISUAL GRAMMAR",direction.visualGrammar)+section("SOUND IDENTITY",direction.soundIdentity)+section("PRODUCTION PILLARS",direction.productionPillars)+section("DISTRIBUTION CUTS",direction.distributionCuts)+section("PROOF, RIGHTS & TRUST",direction.proofAndTrustChecks)+section("ASSUMPTIONS",direction.assumptions)+section("OPEN QUESTIONS",direction.openQuestions)+section("RISK FLAGS",direction.riskFlags)+'<small class="muted">Model: '+esc(direction.model)+' · Review and edit this proposal before using it in a storyboard.</small>':'<div class="empty">No model-backed direction yet. Compile the brief, then explicitly request analysis. The deterministic compiler remains available without a model call.</div>');
 return panel("Model-backed creative direction",body);
}
function modelStoryboardPanel(){
 const project=state.projects.find(item=>item.id===state.activeProject),board=project?.modelStoryboard,direction=project?.modelCreativeDirection;
 const linkedCloudProject=project?.id?state.cloudProjectLinks[project.id]:undefined;
 const scenes=board?.scenes.map((scene,sceneIndex)=>'<article class="project"><small>SCENE '+String(scene.number).padStart(2,"0")+' · '+scene.durationSeconds+' SEC · '+scene.shots.length+' SHOT(S)</small><label>Scene title<input data-model-storyboard-scene-field="title" data-scene-index="'+sceneIndex+'" value="'+esc(scene.title)+'"></label><label>Slugline<input data-model-storyboard-scene-field="slugline" data-scene-index="'+sceneIndex+'" value="'+esc(scene.slugline)+'"></label><label>Scene purpose<textarea data-model-storyboard-scene-field="purpose" data-scene-index="'+sceneIndex+'">'+esc(scene.purpose)+'</textarea></label><details><summary>Review and edit '+scene.shots.length+' shot(s)</summary>'+scene.shots.map((shot,shotIndex)=>'<div class="shot-body"><small>SHOT '+String(shot.number).padStart(3,"0")+' · '+shot.durationSeconds+' SEC · '+esc(shot.shotType.toUpperCase())+'</small><b>'+esc(shot.framing)+' · '+esc(shot.angle)+' · '+esc(shot.movement)+'</b><label>Action<textarea data-model-storyboard-shot-field="action" data-scene-index="'+sceneIndex+'" data-shot-index="'+shotIndex+'">'+esc(shot.action)+'</textarea></label><label>Still-image prompt<textarea data-model-storyboard-shot-field="visualPrompt" data-scene-index="'+sceneIndex+'" data-shot-index="'+shotIndex+'">'+esc(shot.visualPrompt)+'</textarea></label><label>Motion prompt<textarea data-model-storyboard-shot-field="motionPrompt" data-scene-index="'+sceneIndex+'" data-shot-index="'+shotIndex+'">'+esc(shot.motionPrompt)+'</textarea></label><label>Proof reference<textarea data-model-storyboard-shot-field="proofReference" data-scene-index="'+sceneIndex+'" data-shot-index="'+shotIndex+'">'+esc(shot.proofReference)+'</textarea></label><div class="form-grid"><label>Continuity in<textarea data-model-storyboard-shot-field="continuityIn" data-scene-index="'+sceneIndex+'" data-shot-index="'+shotIndex+'">'+esc(shot.continuityIn)+'</textarea></label><label>Continuity out<textarea data-model-storyboard-shot-field="continuityOut" data-scene-index="'+sceneIndex+'" data-shot-index="'+shotIndex+'">'+esc(shot.continuityOut)+'</textarea></label></div><label>Duration (seconds)<input type="number" min="1" max="60" step="1" data-model-storyboard-shot-field="durationSeconds" data-scene-index="'+sceneIndex+'" data-shot-index="'+shotIndex+'" value="'+shot.durationSeconds+'"></label><small class="muted">Transition: '+esc(shot.transitionOut)+' · Sound: '+esc(shot.soundCue)+'</small></div>').join('')+'</details></article>').join('')||'';
 const total=board?.scenes.reduce((sum,scene)=>sum+scene.shots.reduce((n,shot)=>n+shot.durationSeconds,0),0)||0;
 const body=(state.storyboardAiBusy?'<p class="muted">The model is compiling scenes and timed shots. No media provider is being called.</p>':'')+(state.storyboardAiMessage?'<p class="notice">'+esc(state.storyboardAiMessage)+'</p>':'')+(board?'<div class="creative-plan-meta"><span class="status">Model-generated storyboard · editable draft</span><span>'+esc(board.model)+'</span><span>'+esc(board.generatedAt)+'</span><span>'+total+' / '+board.targetDurationSeconds+' sec</span><button class="secondary" data-model-storyboard-export>Export JSON ↓</button><button class="primary" data-model-storyboard-create-timeline '+(linkedCloudProject?.id?'':'disabled title="Save this production to an authorized cloud project first"')+'>Create cloud timeline ↗</button></div>'+(total===board.targetDurationSeconds?'<p class="notice">Shot durations match the target runtime.</p>':'<p class="notice">Review timing: edited shot durations total '+total+' seconds; target is '+board.targetDurationSeconds+' seconds.</p>')+'<p>'+esc(board.logline)+'</p><div class="notice">PLANNING ONLY · Review the creative direction, rights and character references before generation. No provider has been called and no credits have been spent.</div><section class="storyboard-generation-controls"><div class="eyebrow">APPROVED VIDEO GENERATION</div><p class="muted">Run a fresh server-side provider/model/price check, approve an exact budget ceiling, then submit the reviewed shots to the durable cloud queue. Provider execution remains separately gated.</p><label class="rights-confirm"><input type="checkbox" data-model-storyboard-rights> I confirm that the prompts and any referenced material are rights-cleared, and that no unapproved real-person likeness or voice is requested.</label><button class="secondary" data-storyboard-preflight="model" '+(linkedCloudProject?.id?'':'disabled title="Save this production to an authorized cloud project first"')+'>Check generation readiness</button><div class="notice" data-storyboard-preflight-result hidden></div><div class="notice" data-storyboard-approval-controls hidden><b>Approve production budget</b><p>Confirm the verified quote ceiling. This records approval only; it does not submit provider requests or reserve credits.</p><label>Maximum approved budget (<span data-storyboard-budget-currency></span>)</label><input type="number" min="0" step="0.000001" data-storyboard-budget placeholder="Enter budget ceiling"><button class="primary" data-storyboard-approve>Record budget approval</button></div><div class="notice" data-storyboard-approval-result hidden></div><div class="notice" data-storyboard-submit-controls '+(state.videoApproval?.localProjectId===project?.id&&state.videoApproval?.storyboardSource==="model"?'':'hidden')+'><b>Cloud generation queue</b><p>Submit approved shots to the durable cloud queue. This creates jobs only; provider execution occurs in the separately enabled worker.</p><button class="primary" data-storyboard-submit>Submit approved shots to cloud queue</button></div><div class="notice" data-storyboard-submit-result hidden></div><div class="notice" data-storyboard-job-status '+(state.videoApproval?.submitted&&state.videoApproval?.localProjectId===project?.id&&state.videoApproval?.storyboardSource==="model"?'':'hidden')+'>'+esc(state.videoApproval?.statusSummary||'Generation jobs are queued.')+'</div><button class="secondary" data-storyboard-refresh-jobs '+(state.videoApproval?.submitted&&state.videoApproval?.localProjectId===project?.id&&state.videoApproval?.storyboardSource==="model"?'':'hidden')+'>Refresh generation progress</button>'+(state.videoApproval?.submitted&&state.videoApproval?.localProjectId===project?.id&&state.videoApproval?.storyboardSource==="model"?'<div class="video-generation-jobs">'+(state.videoApproval.jobStatuses||[]).map(job=>'<div class="video-generation-job"><span>Shot '+(job.shotIndex+1)+' · '+esc(job.status)+' · '+job.progress+'%</span>'+(["queued","processing","running"].includes(job.status)?'<button class="secondary" data-storyboard-cancel="'+esc(job.jobId)+'">Cancel job</button>':'')+'</div>').join("")+'</div>':'')+(state.videoApproval?.status==="succeeded"&&state.videoApproval?.localProjectId===project?.id&&state.videoApproval?.storyboardSource==="model"&&!state.videoApproval?.timelineCreated?'<button class="primary" data-storyboard-build-generated-timeline>Build timeline from completed shots ↗</button>':'')+'</section><div class="project-grid">'+scenes+'</div><small class="muted">Input fingerprint '+esc(board.inputHash.slice(0,12))+'… · Review character suggestions, proof references and rights before production.</small>':'<div class="empty">Generate a model-backed Creative Director proposal first. The storyboard compiler will turn its reviewed story beats and visual grammar into editable scenes and timed shots.</div>');
 return panel("Model-backed storyboard compiler",body)+(direction?'<div class="section-title"><button class="primary" data-creative-storyboard-generate '+(state.storyboardAiBusy?'disabled':'')+'>'+(board?'Regenerate model storyboard':'Compile model storyboard')+' ↗</button></div>':'');
}
function projects(){return state.projects.length?'<div class="project-grid">'+state.projects.map(p=>'<article class="project"><small>'+esc(p.style)+' · '+(p.creativeDNA?.completenessScore??"—")+'% brief coverage</small><b>'+esc(p.name)+'</b><p>'+esc(p.brief)+'</p><span>'+esc(p.audience||"Audience not specified")+'</span><button class="secondary" data-resume-project="'+esc(p.id)+'">Open this brief →</button></article>').join("")+'</div>':'<div class="empty">No projects yet. Create a brief to start.</div>';}
function renderCreativeStoryboard(project?:Project){
 const board=project?.storyboard;if(!board)return "";
 const linkedCloudProject=project?.id?state.cloudProjectLinks[project.id]:undefined;
 return '<section class="panel"><div class="section-title"><div><div class="eyebrow">02 · SHOT-READY STORYBOARD</div><h2>'+esc(board.title)+'</h2><p>'+board.durationSeconds+' seconds · '+board.sceneCount+' scenes · '+board.shotCount+' timed shots</p></div><button class="secondary" data-storyboard-export>Export storyboard JSON ↓</button><button class="primary" data-storyboard-create-timeline '+(linkedCloudProject?.id?'':'disabled title="Save this production to an authorized cloud project first"')+'>Create editable cloud timeline ↗</button><button class="primary" data-storyboard-create-series>Open in Series Producer ↗</button><button class="secondary" data-storyboard-preflight >Check generation readiness</button></div><div class="notice">PLANNING ONLY · No provider was called and no credits were spent. Review and edit shot direction in the Series Producer before generation.</div><label class="rights-confirm"><input type="checkbox" data-creative-storyboard-rights> I confirm that the prompts and any referenced material are rights-cleared, and that no unapproved real-person likeness or voice is requested.</label><div class="notice" data-storyboard-preflight-result hidden></div><div class="notice" data-storyboard-approval-controls hidden><b>Approve production budget</b><p>Confirm the verified quote ceiling. This records approval only; it does not submit generation or reserve provider credits.</p><label>Maximum approved budget (<span data-storyboard-budget-currency></span>)</label><input type="number" min="0" step="0.000001" data-storyboard-budget placeholder="Enter budget ceiling"><button class="primary" data-storyboard-approve>Record budget approval</button></div><div class="notice" data-storyboard-approval-result hidden></div><div class="notice" data-storyboard-submit-controls '+(state.videoApproval?.localProjectId===project?.id&&(!state.videoApproval?.storyboardSource||state.videoApproval?.storyboardSource==="creative")?'':'hidden')+'><b>Cloud generation queue</b><p>Submit the approved production to the durable cloud queue. This creates jobs only; paid provider execution remains separately gated on the worker.</p><button class="primary" data-storyboard-submit>Submit approved shots to cloud queue</button></div><div class="notice" data-storyboard-submit-result hidden></div><div class="notice" data-storyboard-job-status '+(state.videoApproval?.submitted&&state.videoApproval?.localProjectId===project?.id&&(!state.videoApproval?.storyboardSource||state.videoApproval?.storyboardSource==="creative")?'':'hidden')+'>'+esc(state.videoApproval?.statusSummary||'Generation jobs are queued.')+'</div><button class="secondary" data-storyboard-refresh-jobs '+(state.videoApproval?.submitted&&state.videoApproval?.localProjectId===project?.id&&(!state.videoApproval?.storyboardSource||state.videoApproval?.storyboardSource==="creative")?'':'hidden')+'>Refresh generation progress</button>'+(state.videoApproval?.status==="succeeded"&&state.videoApproval?.projectId===linkedCloudProject?.id&&state.videoApproval?.localProjectId===project?.id&&(!state.videoApproval?.storyboardSource||state.videoApproval?.storyboardSource==="creative")&&!state.videoApproval?.timelineCreated?'<button class="primary" data-storyboard-build-generated-timeline>Build timeline from completed shots ↗</button>':'')+(state.videoApproval?.submitted&&state.videoApproval?.localProjectId===project?.id&&(!state.videoApproval?.storyboardSource||state.videoApproval?.storyboardSource==="creative")?'<div class="video-generation-jobs">'+(state.videoApproval.jobStatuses||[]).map(job=>'<div class="video-generation-job"><span>Shot '+(job.shotIndex+1)+' · '+esc(job.status)+' · '+job.progress+'%</span>'+(["queued","processing","running"].includes(job.status)?'<button class="secondary" data-storyboard-cancel="'+esc(job.jobId)+'">Cancel job</button>':'')+'</div>').join("")+'</div>':'')+'<div class="project-grid">'+board.scenes.map(scene=>'<article class="project"><small>SCENE '+String(scene.sequence).padStart(2,"0")+' · '+scene.durationSeconds+' SEC · '+scene.shots.length+' SHOTS</small><b>'+esc(scene.title)+'</b><p>'+esc(scene.purpose)+'</p><details><summary>Review shot directions</summary>'+scene.shots.map(shot=>'<div class="shot-body"><small>SHOT '+String(shot.sequence).padStart(3,"0")+' · '+shot.durationSeconds+' SEC · '+esc(shot.role.toUpperCase())+'</small><b>'+esc(shot.framing)+'</b><p>'+esc(shot.prompt)+'</p><small>'+esc(shot.camera)+' · '+esc(shot.movement)+'</small></div>').join("")+'</details><small>'+esc(scene.proofNote)+'</small></article>').join("")+'</div><p class="muted">Missing inputs: '+(board.missingInputs.length?board.missingInputs.map(esc).join(" · "):"None identified")+'</p></section>';
}
function director(){return header("CREATIVE INTELLIGENCE","AI Director","Turn a concept into a distinctive creative system: audience promise, emotional journey, visual grammar, sound identity, story beats and distribution cuts.",'<button class="secondary" data-action="export">Export project</button>'+(state.activeProject?'<button class="secondary" data-creative-director-generate '+(state.directorAiBusy?'disabled':'')+'>'+(state.projects.find(item=>item.id===state.activeProject)?.modelCreativeDirection?'Regenerate model direction':'Ask AI Director')+' ↗</button><button class="primary" data-action="publish-brief-cloud">Save production to cloud ↗</button>':''))+
'<div class="two-col"><section class="panel"><div class="eyebrow">01 · CREATIVE DNA COMPILER</div><h2>What are we making—and why will it matter?</h2><p class="muted">A stronger brief produces a more recognizable production. Complete the direction fields; the deterministic compiler creates an editable plan without a model call; optional model-backed analysis is a separate, explicit request through the configured text gateway.</p><form id="director"><label>Project title</label><input name="name" maxlength="120" placeholder="The future of clean energy" required><label>Core idea / brief</label><textarea name="brief" rows="4" maxlength="5000" required placeholder="What is happening, who is involved, what changes, and why should anyone care?">'+esc(state.prompt)+'</textarea><div class="form-grid"><div><label>Audience</label><input name="audience" maxlength="180" placeholder="Who should care?"></div><div><label>Primary channel</label><select name="channel"><option>YouTube</option><option>TikTok</option><option>Instagram Reels</option><option>Website / landing page</option><option>Broadcast / cinema</option><option>Multi-channel campaign</option><option>Internal / presentation</option></select></div></div><div class="form-grid"><div><label>Creative style</label><select name="style">'+options(["Cinematic documentary","Premium commercial","Photoreal editorial","Bold social-first","Educational explainer","Stylized animation","Experimental / mixed media","Human-first reportage"])+'</select></div><div><label>Target duration</label><select name="duration">'+options(["15 seconds","30 seconds","60 seconds","90 seconds","3 minutes","5–10 minutes","10–30 minutes"])+'</select></div></div><label>Desired audience feeling</label><input name="desiredFeeling" maxlength="160" placeholder="Wonder, trust, urgency, hope, delight…"><label>What makes this different?</label><textarea name="differentiator" rows="2" maxlength="800" placeholder="The distinctive angle, mechanism, perspective or experience—not just the topic."></textarea><label>Proof, demonstration or source</label><textarea name="proof" rows="2" maxlength="800" placeholder="What can we show or verify that makes the promise credible?"></textarea><label>One audience action</label><input name="callToAction" maxlength="240" placeholder="What should viewers do, feel or understand next?"><div class="form-grid"><div><label>Visual signature</label><textarea name="visualSignature" rows="2" maxlength="500" placeholder="Color, framing, motif, movement or visual metaphor"></textarea></div><div><label>Sound signature</label><textarea name="soundSignature" rows="2" maxlength="500" placeholder="Music character, recurring cue, texture or silence"></textarea></div></div><label>Constraints and rights</label><textarea name="constraints" rows="2" maxlength="800" placeholder="Budget, deadlines, aspect ratios, brand rules, permissions, locations, accessibility…"></textarea><button class="primary wide">Compile Creative DNA →</button></form></section>'+panel("Creative blueprint",state.plan?'<div class="creative-plan-meta"><span class="status">Structured direction</span><span>'+esc(String(state.projects.find(project=>project.id===state.activeProject)?.creativeDNA?.completenessScore??"—"))+'% brief completeness</span></div><pre class="plan">'+esc(state.plan)+'</pre>':'<div class="empty">Your creative promise, hook angles, emotional journey, visual grammar, sound identity, story beats and preflight checks will appear here.</div>')+'</div>'+renderCreativeStoryboard(state.projects.find(project=>project.id===state.activeProject))+modelCreativeDirectionPanel()+modelStoryboardPanel()+'<div class="section-title"><div class="eyebrow">PROJECT RECORD</div><h2>Projects</h2></div>'+projects();}

async function publishSeriesToCloud(){
 const series=state.seriesPlans.find(item=>item.id===state.activeSeriesId);if(!series){state.cloudMessage="Create or open a series first.";return;}
 state.cloudMessage="Saving series bible, seasons and episode plans…";render();
 try{const existing=state.cloudProjects.find(item=>item.id===state.cloudProjectId);const settings={...(existing?.settings||{}),schemaVersion:2,creativeProduction:{...(existing?.settings?.creativeProduction||{}),version:2,seriesPlans:state.seriesPlans,activeSeriesId:series.id}};
 let saved:{id:string;name:string;revision:number};
 if(existing){const result=await apiRequest<{project:{id:string;name:string;revision:number}}>("/api/cloud/projects/"+existing.id,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({expectedRevision:existing.revision,name:existing.name,description:existing.description||series.premise,settings})});saved=result.project;}
 else{const result=await apiRequest<{project:{id:string;name:string;revision:number}}>("/api/cloud/projects",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name:series.title,description:series.premise,settings})});saved=result.project;}
 state.cloudProjectId=saved.id;state.cloudMessage="Series bible and episode plans saved to the private cloud project.";await loadCloudWorkspace();return true;
 }catch(error){state.cloudMessage=error instanceof Error?error.message:"Could not save the series.";render();return false;}
}

async function createEpisodeTimeline(episodeId:string){
 const series=state.seriesPlans.find(item=>item.id===state.activeSeriesId),episode=series?.seasons.flatMap(season=>season.episodes).find(item=>item.id===episodeId);
 if(!series||!episode){state.cloudMessage="Open a valid series episode first.";render();return;}
 if(!await publishSeriesToCloud())return;
 try{
  const timeline=buildEpisodeTimelineDocument(series,episode,state.cloudProjectId);
  await apiRequest<{timeline:{id:string;name:string;revision:number}}>("/api/cloud/timelines",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({projectId:state.cloudProjectId,name:timeline.name,timeline})});
  state.cloudMessage="Editing timeline created for "+episode.title+". "+timeline.markers.length+" scene and shot markers are ready; add approved media assets to populate tracks.";
  state.tab="cloud";await loadCloudWorkspace();
 }catch(error){state.cloudMessage=error instanceof Error?error.message:"Could not create the episode timeline.";state.tab="cloud";render();}
}

async function loadTransformationPlans(projectId:string){
 if(!projectId){state.transformationDrafts=[];return;}
 const result=await apiRequest<{plans:Array<{id:string;projectId:string;sourceAssetId:string;operation:string;prompt:string;durationSeconds:number;referenceAssetIds:string[];preservation:string[];status:"draft"|"approved"|"queued"|"running"|"succeeded"|"failed"|"cancelled";rightsConfirmed:boolean;subjectConsentConfirmed:boolean;createdAt:string}>}>("/api/cloud/transformations?projectId="+encodeURIComponent(projectId));
 state.transformationDrafts=(result.plans||[]).map(plan=>({
  id:plan.id,projectId:plan.projectId,sourceAssetId:plan.sourceAssetId,
  sourceName:state.cloudAssets.find(asset=>asset.id===plan.sourceAssetId)?.name||"Private source video",
  operation:plan.operation,targetDescription:plan.prompt,prompt:plan.prompt,
  durationSeconds:plan.durationSeconds,referenceAssetIds:plan.referenceAssetIds||[],
  preserve:plan.preservation||[],rightsConfirmed:true,subjectConsentConfirmed:plan.subjectConsentConfirmed,
  createdAt:plan.createdAt,status:plan.status,
  execution:{mode:"draft",submitted:false,requiresApproval:true}
 }));
}
async function loadTransformationReadiness(projectId:string){
 if(!projectId){state.transformationReadiness=null;return;}
 try{
  const result=await apiRequest<{readiness:TransformationReadiness}>("/api/cloud/transformations/readiness?projectId="+encodeURIComponent(projectId));
  state.transformationReadiness=result.readiness;
 }catch{state.transformationReadiness=null;}
}
async function loadCloudWorkspace(){
 state.cloudLoading=true;state.cloudMessage="Checking private cloud storage readiness…";state.cloudMediaReady=null;render();
 try{
  const health=await apiRequest<{cloudMedia?:{enabled:boolean;ready:boolean}}>("/api/health");
  state.cloudMediaReady=health.cloudMedia?.ready===true;
  if(!state.cloudMediaReady){
   state.cloudProjects=[];state.cloudAssets=[];state.cloudTimelines=[];state.transformationDrafts=[];state.transformationReadiness=null;
   state.cloudMessage="Cloud media is not configured on this server. Production currently uses local SQLite and disk storage. Private cloud uploads stay disabled until a dedicated Supabase project, schema, service credentials and private bucket are verified.";
   return;
  }
  const result=await apiRequest<{projects:Array<{id:string;name:string;description?:string;revision:number;settings?:Record<string,unknown>&{creativeProduction?:CloudCreativeProduction}}>}>("/api/cloud/projects");
  state.cloudProjects=result.projects||[];
  if(!state.cloudProjectId||!state.cloudProjects.some(p=>p.id===state.cloudProjectId))state.cloudProjectId=state.cloudProjects[0]?.id||"";
  const selectedCloudProject=state.cloudProjects.find(project=>project.id===state.cloudProjectId);
  const savedProduction=selectedCloudProject?.settings?.creativeProduction;
  const savedBrief=savedProduction?.project;
  if(savedBrief?.id&&savedBrief.name&&savedBrief.brief&&savedProduction?.blueprint){
   const restoredProject:Project={...savedBrief,creativeDNA:savedProduction.creativeDNA,storyboard:savedProduction.storyboard||undefined};
   state.projects=[restoredProject,...state.projects.filter(project=>project.id!==restoredProject.id)];
   state.activeProject=restoredProject.id;state.prompt=restoredProject.brief;state.plan=savedProduction.blueprint;
   state.cloudProjectLinks[restoredProject.id]={id:selectedCloudProject!.id,revision:selectedCloudProject!.revision};
  }
  const savedSeries=savedProduction?.seriesPlans;
  if(Array.isArray(savedSeries)){state.seriesPlans=savedSeries;state.activeSeriesId=selectedCloudProject?.settings?.creativeProduction?.activeSeriesId||savedSeries[0]?.id||"";}
  const query=state.cloudProjectId?"?projectId="+encodeURIComponent(state.cloudProjectId):"";
  const assets=await apiRequest<{assets:Array<{id:string;name:string;mediaType:string;size:number;sha256:string;createdAt:string}>}>("/api/cloud/assets"+query);
  state.cloudAssets=assets.assets||[];
  await loadTransformationPlans(state.cloudProjectId);
  await loadTransformationReadiness(state.cloudProjectId);
  const timelines=await apiRequest<{timelines:Array<{id:string;name:string;revision:number;updatedAt:string}>}>("/api/cloud/timelines"+query);
  state.cloudTimelines=timelines.timelines||[];state.cloudMessage="Private cloud workspace connected.";
 }catch(error){state.cloudMessage=error instanceof Error?error.message:"Cloud workspace is unavailable. Check Supabase sign-in and cloud API configuration.";state.cloudAssets=[];state.transformationDrafts=[];}
 finally{state.cloudLoading=false;render();}
}
