function trackCustomerSuccessEvent(eventType:"session_started"|"workspace_opened"|"project_created"|"render_completed"|"asset_uploaded"|"workflow_completed"|"tutorial_completed"|"billing_viewed"){
 const eventKey=uid();
 void apiRequest("/api/customer-success/events",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({eventType,eventKey})}).catch(()=>{});
}
async function loadBillingWorkspace(){
 billingState.loading=true;billingState.error="";render();
 try{
  const [subscription,plans,transactions,invoices,notifications,loyalty,referrals,success,health]=await Promise.all([
   apiRequest<{subscription:BillingSubscription|null}>("/api/billing/subscription"),
   apiRequest<{plans:BillingPlan[]}>("/api/billing/plans"),
   apiRequest<{transactions:Array<Record<string,unknown>>}>("/api/billing/transactions?limit=20"),
   apiRequest<{invoices:Array<Record<string,unknown>>}>("/api/billing/invoices?limit=20"),
   apiRequest<{notifications:Array<Record<string,unknown>>}>("/api/billing/notifications?limit=20"),
   apiRequest<{loyalty:{rewards:Array<Record<string,unknown>>;events:Array<Record<string,unknown>>;creditBalance:number;offer:Record<string,unknown>|null}}>("/api/billing/loyalty"),
   apiRequest<{referrals:{code:string|null;codeStatus:string;referrals:Array<Record<string,unknown>>;rewardsEarned:number;offer:Record<string,unknown>|null}}>("/api/billing/referrals"),
   apiRequest<{success:{progress:Array<Record<string,unknown>>;milestones:Array<Record<string,unknown>>;points:number;completedCount:number;totalCount:number}}>("/api/customer-success/me"),
   apiRequest<{billing?:{paddlePesapal:{ready:boolean;enabled:boolean;paddle:{configured:boolean;environment:string};pesapal:{configured:boolean;environment:string}}}}>("/api/health")
  ]);
  billingState.subscription=subscription.subscription;billingState.plans=plans.plans||[];
  billingState.transactions=transactions.transactions||[];billingState.invoices=invoices.invoices||[];
  billingState.notifications=notifications.notifications||[];billingState.loyalty=loyalty.loyalty||{rewards:[],events:[],creditBalance:0,offer:null};billingState.referrals=referrals.referrals||{code:null,codeStatus:"",referrals:[],rewardsEarned:0,offer:null};billingState.success=success.success||{progress:[],milestones:[],points:0,completedCount:0,totalCount:0};
  billingState.events=billingState.subscription?(await apiRequest<{events:Array<Record<string,unknown>>}>("/api/billing/subscription/events?subscriptionId="+encodeURIComponent(billingState.subscription.id))).events||[]:[];
   billingState.providerStatus=health.billing?.paddlePesapal||{ready:false,enabled:false,paddle:{configured:false,environment:"sandbox"},pesapal:{configured:false,environment:"sandbox"}};
 }catch(error){billingState.error=error instanceof Error?error.message:"Could not load billing records. Sign in again and retry.";}
 finally{billingState.loading=false;if(state.tab==="billing")render();}
}
async function manageBilling(action:string,planCode=""){
 const sub=billingState.subscription;if(!sub)return;
 if(action==="cancel_immediately"&&!confirm("Cancel this subscription immediately? Paid access will stop after the server confirms the request. This does not automatically issue a refund."))return;
 if(action==="cancel_at_period_end"&&!confirm("Schedule cancellation at the end of the current paid period?"))return;
 try{
  const result=await apiRequest<{message?:string}>("/api/billing/subscription/manage",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({subscriptionId:sub.id,action,planCode})});
  billingState.message=result.message||"Subscription settings updated.";await loadBillingWorkspace();
 }catch(error){billingState.error=error instanceof Error?error.message:"Subscription update failed.";render();}
}
function financeMinor(value:unknown,currency="UGX"){const n=Number(value||0);return billingMoney(currency==="UGX"||currency==="JPY"||currency==="KRW"?n:n/100,currency);}

