function startFinanceAutoRefresh(){if(financeRefreshTimer)clearInterval(financeRefreshTimer);financeRefreshTimer=setInterval(()=>{if(state.tab==="finance"&&document.visibilityState==="visible")void loadFinanceWorkspace();},60000);}
