async function exportFinanceReport(kind:string){
 try{
  const result=await apiRequest<{rows:Array<Record<string,unknown>>;generatedAt:string;truncated:boolean}>("/api/admin/finance/export?kind="+encodeURIComponent(kind));
  const rows=result.rows||[];const keys=[...new Set(rows.flatMap(row=>Object.keys(row)))];
  const cell=(value:unknown)=>'"'+String(value??"").replaceAll('"','""')+'"';
  const csv=[keys.map(cell).join(","),...rows.map(row=>keys.map(key=>cell(row[key])).join(","))].join("\r\n");
  const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="executive-visuals-"+kind+"-"+new Date().toISOString().slice(0,10)+".csv";a.click();URL.revokeObjectURL(url);
  financeState.error=result.truncated?"Export reached the configured row limit; narrow the reporting period before relying on a complete extract.":"";
 }catch(error){financeState.error=error instanceof Error?error.message:"Financial export failed.";}render();
}
function renderNav(){const groups=["Workspace","Explore","Plan & direct","Create","Refine","Manage"];$<HTMLElement>("#nav").innerHTML=groups.map(g=>'<div class="nav-group"><small>'+g+'</small>'+tabs.filter(t=>t.group===g&&(t.id!=="admin"||isAdminOperationsAllowed())).map(t=>'<button class="nav-item '+(state.tab===t.id?"active":"")+'" data-tab="'+t.id+'"><i>'+t.icon+'</i><span>'+t.label+'</span></button>').join("")+'</div>').join("");}
function render(){renderNav();const views:Record<Tab,()=>string>={home,explore,cloud:cloudWorkspace,knowledge:renderKnowledgeWorkspace,series,director,canvas,characters,cinema,images,video,voice,enhance,campaigns,library,engines,settings,capabilities,provenance,runtime,readiness,billing:billingWorkspace,finance:financeWorkspace,admin:renderAdminOperationsWorkspace};$<HTMLElement>("#view").innerHTML=views[state.tab]();$<HTMLElement>("#view").dataset.knowledgeView=state.tab==="knowledge"?"true":"false";$<HTMLElement>("#view").dataset.adminOperations=state.tab==="admin"?"true":"false";$<HTMLElement>("#crumb").textContent=tabs.find(t=>t.id===state.tab)?.label||"Workspace";}
function exportData(){const blob=new Blob([JSON.stringify({product:"EXECUTIVE VISUALS",schemaVersion:2,projects:state.projects,tasks:state.tasks,shots:state.shots,characters:state.characters,seriesPlans:state.seriesPlans,brandKit:state.brandKit,campaignTemplates:state.campaignTemplates,assets:state.assets,workflow:state.graph,transformationDrafts:state.transformationDrafts},null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="executive-visuals-project.json";a.click();URL.revokeObjectURL(url);}
async function publishBriefToCloud(){
 const project=state.projects.find(item=>item.id===state.activeProject);
 if(!project){state.cloudMessage="Create or select a creative brief first.";state.tab="director";render();return;}
 state.cloudMessage="Saving the production brief and creative bible…";render();
 try{
  const duration=state.plan.match(/DURATION:\s*([^\n]+)/)?.[1]||"Not specified";
  const existingSettings=state.cloudProjects.find(item=>item.id===state.cloudProjectLinks[project.id]?.id)?.settings||{};
  const settings={...existingSettings,schemaVersion:1,creativeProduction:{version:3,project:{id:project.id,name:project.name,brief:project.brief,audience:project.audience,style:project.style,duration,created:project.created},blueprint:state.plan,creativeDNA:project.creativeDNA||null,storyboard:project.storyboard||null,shots:state.shots,characters:state.characters,variants:state.variants,seriesPlans:state.seriesPlans}};
  const link=state.cloudProjectLinks[project.id];
  let saved:{id:string;name:string;revision:number};
  if(link){
   const result=await apiRequest<{project:{id:string;name:string;revision:number}}>("/api/cloud/projects/"+link.id,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({expectedRevision:state.cloudProjects.find(item=>item.id===link.id)?.revision??link.revision,name:project.name,description:project.brief,settings})});
   saved=result.project;
  }else{
   const result=await apiRequest<{project:{id:string;name:string;revision:number}}>("/api/cloud/projects",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name:project.name,description:project.brief,settings})});
   saved=result.project;
  }
   state.cloudProjectLinks[project.id]={id:saved.id,revision:saved.revision};
  state.cloudProjectId=saved.id;state.cloudMessage="Production saved. Future saves update this same cloud project using revision checks.";
  save();state.tab="cloud";await loadCloudWorkspace();
 }catch(error){state.cloudMessage=error instanceof Error?error.message:"Could not save the production to cloud.";render();}
}
function action(a:string){if(a==="publish-brief-cloud"){void publishBriefToCloud();return;}if(a==="publish-series-cloud"){void publishSeriesToCloud();return;}if(a==="export")exportData();if(a==="validate-graph"){const graph=buildWorkflowGraph();const validation=validateWorkflow(graph);const plan=planWorkflowExecution(graph,{kind:"all"});state.workflowPreview=validation.valid&&plan.valid?"VALID · "+plan.executionOrder.length+" steps\n\nEXECUTION ORDER\n"+plan.executionOrder.map((id,i)=>(i+1)+". "+(graph.nodes.find(n=>n.id===id)?.label||id)).join("\n")+"\n\nNo provider jobs submitted.":"BLOCKED\n"+[...validation.issues,...plan.issues].map(issue=>issue.code+": "+issue.message).join("\n");save();render();}if(a==="add-node"){const n=prompt("Name this workflow step");if(n){state.graph.push(n);save();render();}}if(a==="reset-graph"){state.graph=baseGraph.slice();save();render();}if(a==="shot"){state.shots.push({id:uid(),scene:"New scene",action:"Describe subject action and blocking",camera:"Medium shot",lens:"50mm",movement:"Slow push-in",lighting:"Soft key / natural fill",duration:5});save();render();}if(a==="character"){
 const n=prompt("Character or presenter name");if(!n)return;
 const d=prompt("Visual character bible: appearance, wardrobe, personality and continuity");if(d===null)return;
 const kind=prompt("Identity category: enter FICTIONAL, AUTHORIZED, or NONE.","FICTIONAL")?.trim().toLowerCase();
 let consent:Character["consent"]={kind:"not-granted",scopes:[],evidenceReference:"",expiresAt:""};
 if(kind==="fictional")consent={kind:"fictional",scopes:["likeness","voice","face-animation","lip-sync","identity-transfer"],evidenceReference:"",expiresAt:""};
 if(kind==="authorized"){
  const scopes=(prompt("Authorized scopes (comma-separated): likeness, voice, face-animation, lip-sync, identity-transfer","likeness,voice")||"").split(",").map(x=>x.trim()).filter(Boolean);
  const evidenceReference=prompt("Reference for the signed release or documented permission (do not paste private documents or sensitive data):")||"";
  const expiresAt=prompt("Permission expiry date (YYYY-MM-DD):")||"";
  consent={kind:"authorized",scopes,evidenceReference,expiresAt};
 }
 state.characters.push({id:uid(),name:n,description:d,voice:"Not assigned",consent});save();render();
}if(a==="clip"){const n=prompt("Timeline clip label");if(n)task(n,"Timeline","Timeline record created; source media and render engine required.");}if(a==="clear"&&confirm("Clear browser planning drafts? API-backed projects, assets and jobs will not be deleted.")){localStorage.removeItem(KEY);location.reload();}}

document.addEventListener("click",e=>{
 const t=e.target as HTMLElement,action=t.closest<HTMLElement>("[data-google-drive-action]");
 const exportButton=t.closest<HTMLElement>("[data-cloud-export-asset]");
 if(exportButton){
  const assetId=exportButton.dataset.cloudExportAsset||"";
  void apiRequest<{file:{name:string;webViewLink:string|null}}>("/api/integrations/google-drive/export",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({assetId,projectId:state.cloudProjectId||null})}).then(result=>{state.cloudMessage="Exported "+result.file.name+" to Google Drive."+(result.file.webViewLink?" "+result.file.webViewLink:"");render();}).catch(error=>{state.cloudMessage=error instanceof Error?error.message:"Google Drive export failed.";render();});
  return;
 }
 if(!action)return;
 const mode=action.dataset.googleDriveAction;
 if(mode==="refresh"){googleDriveStatusLoaded=false;void refreshGoogleDriveStatus();return;}
 if(mode==="browse"){void openGoogleDrivePicker();return;}
 if(mode==="connect"){
  void apiRequest<{authorizationUrl:string}>("/api/integrations/google-drive/connect",{method:"POST"}).then(result=>{if(!result.authorizationUrl)throw new Error("Google authorization URL was not returned.");window.location.assign(result.authorizationUrl);}).catch(error=>{googleDriveStatusError=error instanceof Error?error.message:"Google Drive connection could not be started.";googleDriveStatusLoaded=true;render();});
  return;
 }
 if(mode==="disconnect"){
  if(!confirm("Disconnect Google Drive? The saved refresh token will be revoked where possible."))return;
  void apiRequest<{disconnected:boolean;revoked:boolean}>("/api/integrations/google-drive/disconnect",{method:"POST"}).then(result=>{googleDriveConnection={connected:false,email:null,grantedScopes:[]};googleDriveStatusLoaded=true;googleDriveStatusError=result.revoked?"":"Connection removed, but Google revocation could not be confirmed.";render();}).catch(error=>{googleDriveStatusError=error instanceof Error?error.message:"Google Drive could not be disconnected.";render();});
 }
});
